def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # The thin, connected drawing color has many cells with low degree.
    marker = None
    best_score = -1
    for color in counts:
        if color == background:
            continue
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        low = 0
        for r, c in cells:
            degree = sum(
                0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color
                for rr, cc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1))
            )
            low += degree <= 2
        score = low * low / len(cells)
        if score > best_score:
            best_score, marker = score, color

    source_colors = [v for v in counts if v not in (background, marker)]
    if not source_colors:
        return [row[:] for row in grid]

    # Correct isolated wrong-color pixels in the large source patches.
    sources = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in source_colors:
                continue
            local = Counter()
            for rr in range(max(0, r-2), min(h, r+3)):
                for cc in range(max(0, c-2), min(w, c+3)):
                    if grid[rr][cc] in source_colors:
                        local[grid[rr][cc]] += 1
            label = max(source_colors, key=lambda v: (local[v], counts[v]))
            sources.append((r, c, label))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker:
                continue
            nearest_distance = None
            nearest_color = None
            for sr, sc, color in sources:
                distance = (r - sr) ** 2 + (c - sc) ** 2
                if nearest_distance is None or distance < nearest_distance:
                    nearest_distance = distance
                    nearest_color = color
                elif distance == nearest_distance and color == nearest_color:
                    pass
            if nearest_color is not None:
                out[r][c] = nearest_color
    return out
